import type { Locator, Page } from "@playwright/test";
import { animationsFinished, expect, test } from "./fixtures";

// Loading the engine means fetching and compiling ~35 MB of WebAssembly.
const ENGINE_TIMEOUT = 60_000;
// Samples are generated by the engine when they're loaded.
const SAMPLE_TIMEOUT = 30_000;
// Even small queries can take seconds in WebKit on a busy machine.
const QUERY_TIMEOUT = 20_000;

const editor = (page: Page) => page.getByRole("textbox", { name: "SQL editor" });
const summary = (page: Page) => page.getByRole("region", { name: "Query" }).getByText(/ in \d/);

async function openWorkbench(page: Page) {
  await page.goto("/app/");
  await expect(page.getByRole("status")).toHaveText(/^Engine ready/, { timeout: ENGINE_TIMEOUT });
}

/**
 * The focused element, looked for inside shadow roots (the editor is in one): a description of
 * it for failure messages, whether it's on screen, and whether it shows that it has the focus.
 */
async function focused(page: Page) {
  // A dialog fading in isn't visible yet.
  await animationsFinished(page);
  return page.evaluate(() => {
    let element = document.activeElement;
    while (element?.shadowRoot?.activeElement) element = element.shadowRoot.activeElement;
    if (!element || element === document.body) return null;
    const label = element.getAttribute("aria-label") ?? element.textContent ?? "";
    const name = `<${element.tagName.toLowerCase()}> "${label.trim().slice(0, 40)}"`;
    const box = element.getBoundingClientRect();
    const onScreen =
      element.checkVisibility({ opacityProperty: true, visibilityProperty: true }) &&
      box.width > 0 &&
      box.height > 0 &&
      box.bottom > 0 &&
      box.right > 0 &&
      box.top < innerHeight &&
      box.left < innerWidth;
    // The editor shows the focus with its caret; the grid outlines its active cell.
    if (element.classList.contains("cm-content")) return { name, onScreen, indicated: true };
    const activeId = element.getAttribute("aria-activedescendant");
    const marked = activeId ? document.getElementById(activeId) : element;
    const style = marked && getComputedStyle(marked);
    const indicated =
      !!style &&
      ((style.outlineStyle !== "none" && Number.parseFloat(style.outlineWidth) > 0) ||
        style.boxShadow !== "none");
    return { name, onScreen, indicated };
  });
}

/** Whether `target` has the focus, in the document or in its shadow root. */
function hasFocus(target: Locator) {
  return target.evaluate(
    (element) => (element.getRootNode() as Document | ShadowRoot).activeElement === element,
  );
}

/**
 * Presses `key` until `target` has the focus, checking at each stop that the focused element is
 * on screen and shows that it's focused (WCAG 2.4.7 and 2.4.11).
 */
async function pressUntilFocused(page: Page, target: Locator, key = "Tab", limit = 40) {
  for (let presses = 0; presses < limit; presses++) {
    await page.keyboard.press(key);
    const focus = await focused(page);
    if (focus) {
      expect(focus.onScreen, `${focus.name} is on screen when focused`).toBe(true);
      expect(focus.indicated, `${focus.name} shows that it has the focus`).toBe(true);
    }
    if (await hasFocus(target)) return;
  }
  throw new Error(`${key} never reached ${target}`);
}

test.describe("Keyboard", () => {
  test("loads a sample, queries it, reads, charts and browses templates with only the keyboard", async ({
    page,
  }) => {
    test.setTimeout(120_000);
    await openWorkbench(page);

    const loadSample = page.getByRole("button", { name: "Load sample data" });
    await pressUntilFocused(page, loadSample);
    await page.keyboard.press("Enter");
    const samples = page.getByRole("dialog", { name: "Load sample data" });
    await expect(samples).toBeVisible();
    await pressUntilFocused(page, samples.getByRole("button", { name: /^Quality checks/ }));
    await page.keyboard.press("Enter");
    await expect(samples).toBeHidden({ timeout: SAMPLE_TIMEOUT });
    // Focus goes back to where the dialog was opened from.
    await expect(loadSample).toBeFocused();

    // Tab reaches the editor, and leaves it again: the editor binds no Tab key, so it never
    // holds the focus (WCAG 2.1.2). Escape closes autocomplete first if it's open.
    await pressUntilFocused(page, editor(page));
    await page.keyboard.type("SELECT * FROM quality_checks");
    await page.keyboard.press("Escape");
    await page.keyboard.press("ControlOrMeta+Enter");
    await expect(summary(page)).toHaveText(/ rows in /, { timeout: QUERY_TIMEOUT });

    const grid = page.getByRole("grid", { name: "Results" });
    await pressUntilFocused(page, grid);
    const activeCell = () =>
      grid.evaluate((element) => {
        const cell = document.getElementById(element.getAttribute("aria-activedescendant") ?? "");
        return cell && [cell.closest('[role="row"]')?.ariaRowIndex, cell.ariaColIndex];
      });
    expect(await activeCell()).toEqual(["2", "1"]);
    await page.keyboard.press("ArrowDown");
    await page.keyboard.press("ArrowRight");
    expect(await activeCell()).toEqual(["3", "2"]);

    const chart = page.getByRole("button", { name: "Chart", exact: true });
    await pressUntilFocused(page, chart, "Shift+Tab");
    await page.keyboard.press("Space");
    await expect(chart).toHaveAttribute("aria-pressed", "true");
    await expect(chart).toBeFocused();
    await expect(page.getByRole("img", { name: /^Bar chart of / })).toBeVisible();
    const chartType = page.getByLabel("Chart type");
    await pressUntilFocused(page, chartType);
    await page.keyboard.press("ArrowDown");
    await expect(chartType).toHaveValue("line");
    await expect(page.getByRole("img", { name: /^Line chart of / })).toBeVisible();

    const templatesButton = page.getByRole("button", { name: "Templates" });
    await pressUntilFocused(page, templatesButton, "Shift+Tab");
    await page.keyboard.press("Enter");
    const templates = page.getByRole("dialog", { name: "Templates" });
    await expect(templates).toBeVisible();
    // While the dialog is open, Tab and Shift+Tab stay inside it. Focus passes through a guard
    // just outside the dialog on its way round, so it's checked once it has settled.
    for (const key of ["Tab", "Tab", "Tab", "Shift+Tab", "Shift+Tab", "Shift+Tab", "Shift+Tab"]) {
      await page.keyboard.press(key);
      await expect
        .poll(() => templates.evaluate((dialog) => dialog.contains(document.activeElement)))
        .toBe(true);
    }
    await page.keyboard.press("Escape");
    await expect(templates).toBeHidden();
    await expect(templatesButton).toBeFocused();
  });

  test("skips past the sidebar to the workspace", async ({ page, browserName }) => {
    await page.goto("/app/");

    const skip = page.getByRole("link", { name: "Skip to the workspace" });
    // Playwright's WebKit leaves links out of the Tab order, as Safari does unless "Press Tab to
    // highlight each item" is on, so there the link is focused directly.
    if (browserName === "webkit") await skip.focus();
    else await pressUntilFocused(page, skip, "Tab", 1);
    await page.keyboard.press("Enter");
    await pressUntilFocused(page, page.getByRole("button", { name: "Run", exact: true }), "Tab", 1);
  });
});
